    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            boundary=set()
            exterior=False
            while q:
                y,x=q.popleft(); cells.append((y,x))
                if y in (0,h-1) or x in (0,w-1): exterior=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if not (0<=yy<h and 0<=xx<w):
