                    elif grid[yy][xx]==bg:
                        if (yy,xx) not in seen:
                            seen.add((yy,xx)); q.append((yy,xx))
                    else:
                        boundary.add(grid[yy][xx])
            if not exterior and len(boundary)==1:
                color=next(iter(boundary))
                fill=2 if color==3 else 7
                for y,x in cells: out[y][x]=fill
    return out

